import { Component, Input } from '@angular/core';
import { Pienso } from 'src/app/models/pienso';

@Component({
  selector: 'app-producto',
  templateUrl: './producto.component.html',
  styleUrls: ['./producto.component.css']
})
  export class ProductoComponent {
    @Input() piensoEnviado : Pienso;

  constructor(){
    this.piensoEnviado = new Pienso();
  }



}

<div class="container-fluid">
    <div class="card h-100 text-center">
        <img src="{{piensoEnviado.imagen}}" class="card-img-top" alt="imagen pienso {{piensoEnviado.nombre}}">
        <div class="card-body">
          <h5 class="card-title">{{piensoEnviado.nombre}} - {{piensoEnviado.peso}} kg</h5>
          <p class="card-text">{{piensoEnviado.descripcion}}</p>
          <p class="card-text text-success" style="font-weight: bold">{{piensoEnviado.precio}} €</p>
          <div class="card-footer d-flex flex-column align-items-center">
            <input type="number" max="{{piensoEnviado.stock}}" min="1" value="1" style="margin-bottom: 1em;">
            <a href="#" class="btn btn-primary"> <i class="bi bi-cart-plus"></i>Agregar</a>
        </div>
        </div>
    </div>
  </div>
